 void safeInsets(int left,int right,int top){safeLeft=left;safeRight=right;safeTop=top;if(panel!=null&&overlay!=null){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)panel.getLayoutParams();int width=Math.min(dp(360),Math.max(1,host.getWidth()-left-right));if(p.width!=width||p.topMargin!=top||p.rightMargin!=right){p.width=width;p.topMargin=top;p.rightMargin=right;panel.setLayoutParams(p);}}}
